const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$tests=@(
 'https://forum.thegradcafe.com/rss/1-latest-blog-posts.xml/',
 'https://forum.thegradcafe.com/search/?q=personal%20statement%20editing',
 'https://boredofstudies.org/whats-new/latest-activity',
 'https://boredofstudies.org/forums/'
)
foreach($u in $tests){
  $code = curl.exe -s -o "$env:TEMP\\p.html" -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 30 --compressed $u
  Write-Output "== $code  $u"
  Start-Sleep -Seconds 4
}`;
const r = await tools.pwsh({ description: "Probe GradCafe and BOS endpoints", command: cmd, timeoutMs: 180000 });
console.log(r.kind === 'foreground' ? r.stdout.text + "|E:" + r.stderr.text : JSON.stringify(r));
